-- Authoritative, policy-driven Mission JSA aggregate and Platform Hazard Library.
create table public.platform_jsa_templates(id uuid primary key default gen_random_uuid(),stable_code text not null unique,name text not null,status text not null default'PUBLISHED'check(status in('PUBLISHED','RETIRED')),current_version integer not null default 1 check(current_version>0),created_at timestamptz not null default now());
create table public.platform_jsa_template_versions(id uuid primary key default gen_random_uuid(),template_id uuid not null references public.platform_jsa_templates(id),version_number integer not null check(version_number>0),jurisdiction text not null default'AU',questions jsonb not null check(jsonb_typeof(questions)='array'),rules jsonb not null default'[]'::jsonb check(jsonb_typeof(rules)='array'),published_at timestamptz not null default now(),retired_at timestamptz,unique(template_id,version_number),unique(id,template_id));
create table public.platform_hazards(id uuid primary key default gen_random_uuid(),stable_code text not null unique,name text not null,status text not null default'PUBLISHED'check(status in('PUBLISHED','RETIRED')),current_version integer not null default 1 check(current_version>0),created_at timestamptz not null default now());
create table public.platform_hazard_versions(id uuid primary key default gen_random_uuid(),hazard_id uuid not null references public.platform_hazards(id),version_number integer not null check(version_number>0),description text not null,category text not null,typical_controls jsonb not null default'[]'::jsonb,jurisdiction text not null default'AU',reference_sources jsonb not null default'[]'::jsonb,related_regulations jsonb not null default'[]'::jsonb,provenance jsonb not null default'{}'::jsonb,published_at timestamptz not null default now(),retired_at timestamptz,unique(hazard_id,version_number),unique(id,hazard_id));
create table public.organisation_jsa_policies(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),current_version integer not null default 1 check(current_version>0),created_at timestamptz not null default now(),unique(organisation_id),unique(organisation_id,id));
create table public.organisation_jsa_policy_versions(id uuid primary key default gen_random_uuid(),organisation_id uuid not null,policy_id uuid not null,version_number integer not null check(version_number>0),approval_model text not null check(approval_model in('PIC_SELF_APPROVAL','PIC_PLUS_REVIEWER','DUAL_APPROVAL','RISK_BASED')),approval_rules jsonb not null default'{}'::jsonb,residual_risk_threshold integer not null default 6 check(residual_risk_threshold between 2 and 25),effective_at timestamptz not null default now(),retired_at timestamptz,created_by_internal_user_id uuid,unique(organisation_id,policy_id,version_number),unique(organisation_id,id),foreign key(organisation_id,policy_id)references public.organisation_jsa_policies(organisation_id,id),foreign key(organisation_id,created_by_internal_user_id)references public.internal_users(organisation_id,id));
create table public.mission_jsa_revisions(id uuid primary key default gen_random_uuid(),organisation_id uuid not null,operating_location_id uuid not null,mission_id uuid not null,version_number integer not null check(version_number>0),template_id uuid not null,template_version_id uuid not null,template_version integer not null,policy_id uuid not null,policy_version_id uuid not null,policy_version integer not null,policy_snapshot jsonb not null,template_snapshot jsonb not null,general_comments text,created_at timestamptz not null default now(),created_by_internal_user_id uuid not null,unique(organisation_id,id),unique(organisation_id,mission_id,version_number),foreign key(organisation_id,mission_id)references public.missions(organisation_id,id),foreign key(organisation_id,operating_location_id)references public.operating_locations(organisation_id,id),foreign key(template_version_id,template_id)references public.platform_jsa_template_versions(id,template_id),foreign key(organisation_id,policy_version_id)references public.organisation_jsa_policy_versions(organisation_id,id),foreign key(organisation_id,created_by_internal_user_id)references public.internal_users(organisation_id,id));
create table public.mission_jsa_responses(id uuid primary key default gen_random_uuid(),organisation_id uuid not null,revision_id uuid not null,mission_id uuid not null,question_id text not null,question_snapshot jsonb not null,applicable boolean not null,answer boolean,notes text,unsafe boolean not null default false,rule_evaluation jsonb not null default'{}'::jsonb,unique(organisation_id,revision_id,question_id),foreign key(organisation_id,revision_id)references public.mission_jsa_revisions(organisation_id,id),foreign key(organisation_id,mission_id)references public.missions(organisation_id,id));
create table public.mission_hazard_instances(id uuid primary key default gen_random_uuid(),organisation_id uuid not null,revision_id uuid not null,mission_id uuid not null,triggering_question_id text not null,platform_hazard_id uuid not null,platform_hazard_version_id uuid not null,platform_hazard_version integer not null,platform_hazard_snapshot jsonb not null,risk_category text not null,likelihood integer check(likelihood between 1 and 5),consequence integer check(consequence between 1 and 5),initial_score integer,notes text,unique(organisation_id,revision_id,triggering_question_id),foreign key(organisation_id,revision_id)references public.mission_jsa_revisions(organisation_id,id),foreign key(organisation_id,mission_id)references public.missions(organisation_id,id),foreign key(platform_hazard_version_id,platform_hazard_id)references public.platform_hazard_versions(id,hazard_id));
create table public.mission_risk_control_instances(id uuid primary key default gen_random_uuid(),organisation_id uuid not null,revision_id uuid not null,mission_id uuid not null,hazard_instance_id uuid not null,triggering_question_id text not null,template_control_id text not null,risk_category text not null,required_mitigation text not null,owner_personnel_id uuid,owner_personnel_snapshot jsonb,due_status text not null default'BEFORE_AUTHORISATION'check(due_status in('BEFORE_AUTHORISATION','BEFORE_FLIGHT','MONITOR')),completion_state text not null default'OPEN'check(completion_state in('OPEN','IN_PROGRESS','COMPLETE','NOT_REQUIRED')),completed_at timestamptz,completing_personnel_snapshot jsonb,likelihood integer check(likelihood between 1 and 5),consequence integer check(consequence between 1 and 5),initial_score integer,mitigation text,residual_likelihood integer check(residual_likelihood between 1 and 5),residual_consequence integer check(residual_consequence between 1 and 5),residual_score integer,evidence jsonb not null default'[]'::jsonb,notes text,derivation_provenance jsonb not null default'{}'::jsonb,unique(organisation_id,revision_id,template_control_id),foreign key(organisation_id,revision_id)references public.mission_jsa_revisions(organisation_id,id),foreign key(organisation_id,mission_id)references public.missions(organisation_id,id),foreign key(organisation_id,owner_personnel_id)references public.personnel(organisation_id,id));
create table public.mission_jsa_attachments(id uuid primary key default gen_random_uuid(),organisation_id uuid not null,revision_id uuid not null,mission_id uuid not null,control_instance_id uuid,internal_file_id uuid not null,file_version integer not null check(file_version>0),sha256_checksum text not null check(sha256_checksum~'^[a-f0-9]{64}$'),evidence_type text not null,access_classification text not null check(access_classification in('operational','restricted','private')),provenance jsonb not null default'{}'::jsonb,attached_at timestamptz not null default now(),attached_by_internal_user_id uuid not null,foreign key(organisation_id,revision_id)references public.mission_jsa_revisions(organisation_id,id),foreign key(organisation_id,mission_id)references public.missions(organisation_id,id),foreign key(organisation_id,attached_by_internal_user_id)references public.internal_users(organisation_id,id));
create table public.mission_jsa_approvals(id uuid primary key default gen_random_uuid(),organisation_id uuid not null,operating_location_id uuid not null,mission_id uuid not null,revision_id uuid not null,approval_sequence integer not null default 1,approval_role text not null,approving_personnel_id uuid not null,approving_personnel_version integer not null,approving_personnel_snapshot jsonb not null,policy_requirement_snapshot jsonb not null,approved_at timestamptz not null default now(),approved_by_internal_user_id uuid not null,unique(organisation_id,revision_id,approval_sequence),foreign key(organisation_id,revision_id)references public.mission_jsa_revisions(organisation_id,id),foreign key(organisation_id,mission_id)references public.missions(organisation_id,id),foreign key(organisation_id,approving_personnel_id)references public.personnel(organisation_id,id),foreign key(organisation_id,approved_by_internal_user_id)references public.internal_users(organisation_id,id));

