create function public.ftf_provision_jsa_policy()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$declare p public.organisation_jsa_policies%rowtype;begin insert into public.organisation_jsa_policies(organisation_id)values(new.id)on conflict(organisation_id)do update set organisation_id=excluded.organisation_id returning * into p;insert into public.organisation_jsa_policy_versions(organisation_id,policy_id,version_number,approval_model,approval_rules,residual_risk_threshold)values(new.id,p.id,1,'PIC_SELF_APPROVAL',jsonb_build_object('requirements',jsonb_build_array(jsonb_build_object('role','pilot_in_command','count',1,'selfApproval',true)),'separationOfDuties',false),6)on conflict do nothing;return new;end$$;
create trigger organisations_provision_jsa_policy after insert on public.organisations for each row execute function public.ftf_provision_jsa_policy();
insert into public.organisation_jsa_policies(organisation_id)select id from public.organisations on conflict do nothing;
insert into public.organisation_jsa_policy_versions(organisation_id,policy_id,version_number,approval_model,approval_rules,residual_risk_threshold)select p.organisation_id,p.id,1,'PIC_SELF_APPROVAL',jsonb_build_object('requirements',jsonb_build_array(jsonb_build_object('role','pilot_in_command','count',1,'selfApproval',true)),'separationOfDuties',false),6 from public.organisation_jsa_policies p on conflict do nothing;
create function public.ftf_provision_jsa_permissions()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin insert into public.permissions(organisation_id,code,description)select new.organisation_id,v.code,v.description from(values('mission.jsa.read','View authoritative Mission JSA'),('mission.jsa.write','Save authoritative Mission JSA'),('mission.jsa.approve','Approve Mission JSA when policy requirements are satisfied'))v(code,description)on conflict do nothing;if new.code='admin'then insert into public.role_permissions(organisation_id,role_id,permission_id)select new.organisation_id,new.id,p.id from public.permissions p where p.organisation_id=new.organisation_id and p.code in('mission.jsa.read','mission.jsa.write','mission.jsa.approve')on conflict do nothing;end if;return new;end$$;
create trigger roles_provision_jsa_permissions after insert on public.roles for each row execute function public.ftf_provision_jsa_permissions();
insert into public.permissions(organisation_id,code,description)select o.id,v.code,v.description from public.organisations o cross join(values('mission.jsa.read','View authoritative Mission JSA'),('mission.jsa.write','Save authoritative Mission JSA'),('mission.jsa.approve','Approve Mission JSA when policy requirements are satisfied'))v(code,description)on conflict do nothing;
insert into public.role_permissions(organisation_id,role_id,permission_id)select r.organisation_id,r.id,p.id from public.roles r join public.permissions p on p.organisation_id=r.organisation_id and p.code in('mission.jsa.read','mission.jsa.write','mission.jsa.approve')where r.code='admin'on conflict do nothing;

-- Bounded rule language. Unknown operators fail rather than executing arbitrary expressions.
create function public.ftf_evaluate_jsa_rule(p_rule jsonb,p_facts jsonb,p_responses jsonb)returns boolean language plpgsql immutable as $$declare op text;item jsonb;result boolean;begin if p_rule is null or p_rule='{}'::jsonb then return true;end if;op=p_rule->>'operator';if op='all'then for item in select value from jsonb_array_elements(coalesce(p_rule->'rules','[]'))loop if not public.ftf_evaluate_jsa_rule(item,p_facts,p_responses)then return false;end if;end loop;return true;elsif op='any'then for item in select value from jsonb_array_elements(coalesce(p_rule->'rules','[]'))loop if public.ftf_evaluate_jsa_rule(item,p_facts,p_responses)then return true;end if;end loop;return false;elsif op='equals'then return p_facts->(p_rule->>'field')=p_rule->'value';elsif op='notEquals'then return p_facts->(p_rule->>'field')<>p_rule->'value';elsif op='in'then return(p_rule->'values')@>jsonb_build_array(p_facts->(p_rule->>'field'));elsif op='answeredUnsafe'then return coalesce((select(x->>'unsafe')::boolean from jsonb_array_elements(p_responses)x where x->>'questionId'=p_rule->>'questionId'),false);else raise exception 'unsupported JSA rule operator';end if;end$$;

-- Platform Hazard Library and exact existing Mission Checks template.
insert into public.platform_jsa_templates(id,stable_code,name)values('b1000000-0000-4000-8000-000000000001','MISSION_CHECKS_AU','Mission Checks')on conflict do nothing;
insert into public.platform_hazards(id,stable_code,name)select ('b2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,code,name from(values(1,'MAPS','Maps and charts incomplete'),(2,'WEATHER','Weather unsuitable or undetermined'),(3,'NOTAM','NOTAM not reviewed'),(4,'PEOPLE','People may enter operational area'),(5,'RIGHTS_OF_WAY','Rights of way present'),(6,'LANDING_AREAS','Landing areas unsuitable'),(7,'PUBLIC_SEPARATION','Public separation unavailable'),(8,'OBSTRUCTIONS','Obstructions present'),(9,'INTERFERENCE','Radio or GPS interference'),(10,'VLOS','VLOS or EVLOS unavailable'),(11,'PILOT_ABILITY','Pilot ability mismatch'),(12,'PRIVACY','Privacy concerns'),(13,'SIGNAGE','Signage required'))v(n,code,name)on conflict do nothing;
insert into public.platform_hazard_versions(hazard_id,version_number,description,category,typical_controls,jurisdiction,reference_sources,related_regulations,provenance)select h.id,1,h.name,case when h.stable_code in('WEATHER','PEOPLE','RIGHTS_OF_WAY','PRIVACY')then'ENVIRONMENTAL'when h.stable_code in('PILOT_ABILITY')then'PERSONNEL'else'OPERATIONAL'end,jsonb_build_array(jsonb_build_object('id',lower(h.stable_code)||'-control','description','Document and complete an operational mitigation before authorisation.','dueStatus','BEFORE_AUTHORISATION','completionRequired',true)),'AU','[]','[]',jsonb_build_object('source','existing Spray Command Mission Checks')from public.platform_hazards h on conflict do nothing;
insert into public.platform_jsa_template_versions(id,template_id,version_number,jurisdiction,questions,rules)values('b1000000-0000-4000-8000-000000000101','b1000000-0000-4000-8000-000000000001',1,'AU',(select jsonb_agg(jsonb_build_object('id',q.id,'question',q.question,'mandatory',true,'unsafeAnswer',q.unsafe,'riskCategory',q.category,'hazardId',h.id,'hazardVersionId',hv.id,'hazardVersion',1,'visibilityRule','{}'::jsonb,'control',hv.typical_controls->0)order by q.n)from(values(1,'maps','Have you investigated the necessary maps and charts (either hard copy or electronic) for the area?',false,'OPERATIONAL'),(2,'weather','Have you determined if the weather is suitable for the RPA and the operation?',false,'ENVIRONMENTAL'),(3,'notam','Have you reviewed the NOTAM related to the operations area?',false,'OPERATIONAL'),(4,'people','Is there a possibility of a person moving into the area of operation or landing area during flight?',true,'ENVIRONMENTAL'),(5,'rights-of-way','Are there footpaths, or other rights of way?',true,'ENVIRONMENTAL'),(6,'landing-areas','Is there a suitable take-off and landing areas (including alternate landing area)?',false,'OPERATIONAL'),(7,'public-separation','Is there an ability to maintain 30m horizontal separation from the public?',false,'OPERATIONAL'),(8,'obstructions','Are there obstructions (buildings, trees etc.)?',true,'OPERATIONAL'),(9,'interference','Is there a possible radio or GPS interference (power lines, antennas etc.)?',true,'OPERATIONAL'),(10,'vlos','Will you have the ability to maintain VLOS / EVLOS?',false,'OPERATIONAL'),(11,'pilot-ability','Does the Remote pilot''s ability match the location/task?',false,'PERSONNEL'),(12,'privacy','Are there privacy concerns?',true,'ENVIRONMENTAL'),(13,'signage','Will there be a need for signage?',true,'OPERATIONAL'))q(n,id,question,unsafe,category)join public.platform_hazards h on h.stable_code=upper(replace(q.id,'-','_'))join public.platform_hazard_versions hv on hv.hazard_id=h.id and hv.version_number=1),'[]')on conflict do nothing;

create function public.ftf_read_mission_jsa(p_organisation_id uuid,p_mission_id uuid,p_history boolean default false)returns setof jsonb language sql security definer set search_path=public,pg_temp as $$with r as(select * from public.mission_jsa_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id order by version_number desc limit case when p_history then 2147483647 else 1 end)select to_jsonb(r)||jsonb_build_object('responses',coalesce((select jsonb_agg(to_jsonb(x)order by x.question_id)from public.mission_jsa_responses x where x.organisation_id=r.organisation_id and x.revision_id=r.id),'[]'::jsonb),'hazards',coalesce((select jsonb_agg(to_jsonb(x)order by x.triggering_question_id)from public.mission_hazard_instances x where x.organisation_id=r.organisation_id and x.revision_id=r.id),'[]'::jsonb),'controls',coalesce((select jsonb_agg(to_jsonb(x)order by x.triggering_question_id)from public.mission_risk_control_instances x where x.organisation_id=r.organisation_id and x.revision_id=r.id),'[]'::jsonb),'attachments',coalesce((select jsonb_agg(to_jsonb(x)order by x.attached_at)from public.mission_jsa_attachments x where x.organisation_id=r.organisation_id and x.revision_id=r.id),'[]'::jsonb),'approvals',coalesce((select jsonb_agg(to_jsonb(x)order by x.approval_sequence)from public.mission_jsa_approvals x where x.organisation_id=r.organisation_id and x.revision_id=r.id),'[]'::jsonb))from r;$$;

create function public.ftf_save_mission_jsa(p_organisation_id uuid,p_actor_internal_user_id uuid,p_mission_id uuid,p_expected_version integer,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare m public.missions%rowtype;tv public.platform_jsa_template_versions%rowtype;pv public.organisation_jsa_policy_versions%rowtype;p public.organisation_jsa_policies%rowtype;r public.mission_jsa_revisions%rowtype;q jsonb;submitted jsonb;haz public.platform_hazard_versions%rowtype;hinst public.mission_hazard_instances%rowtype;c jsonb;owner public.personnel%rowtype;a jsonb;current integer;applicable boolean;answer boolean;unsafe boolean;begin select * into m from public.missions where organisation_id=p_organisation_id and id=p_mission_id and archived_at is null for update;if not found then return jsonb_build_object('not_found',true);end if;if m.status<>'planning'then return jsonb_build_object('lifecycle_conflict',true);end if;if not exists(select 1 from public.memberships x join public.membership_operating_location_assignments l on l.organisation_id=x.organisation_id and l.membership_id=x.id where x.organisation_id=p_organisation_id and x.internal_user_id=p_actor_internal_user_id and x.is_active and x.archived_at is null and l.operating_location_id=m.operating_location_id and l.is_active and l.archived_at is null)then return jsonb_build_object('location_forbidden',true);end if;select coalesce(max(version_number),0)into current from public.mission_jsa_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id;if current<>p_expected_version then return jsonb_build_object('conflict',true,'current_version',current);end if;select * into tv from public.platform_jsa_template_versions where template_id='b1000000-0000-4000-8000-000000000001'and retired_at is null order by version_number desc limit 1;select * into p from public.organisation_jsa_policies where organisation_id=p_organisation_id;select * into pv from public.organisation_jsa_policy_versions where organisation_id=p_organisation_id and policy_id=p.id and retired_at is null order by version_number desc limit 1;insert into public.mission_jsa_revisions(organisation_id,operating_location_id,mission_id,version_number,template_id,template_version_id,template_version,policy_id,policy_version_id,policy_version,policy_snapshot,template_snapshot,general_comments,created_by_internal_user_id)values(p_organisation_id,m.operating_location_id,p_mission_id,current+1,tv.template_id,tv.id,tv.version_number,p.id,pv.id,pv.version_number,to_jsonb(pv),to_jsonb(tv),nullif(p_payload->>'generalComments',''),p_actor_internal_user_id)returning * into r;
for q in select value from jsonb_array_elements(tv.questions)loop applicable=public.ftf_evaluate_jsa_rule(q->'visibilityRule',coalesce(p_payload->'missionFacts','{}'),coalesce(p_payload->'responses','[]'));select x into submitted from jsonb_array_elements(coalesce(p_payload->'responses','[]'))x where x->>'questionId'=q->>'id'limit 1;answer=case when submitted?'answer'and submitted->'answer'<>'null'::jsonb then(submitted->>'answer')::boolean else null end;unsafe=answer is not null and answer=(q->>'unsafeAnswer')::boolean;insert into public.mission_jsa_responses(organisation_id,revision_id,mission_id,question_id,question_snapshot,applicable,answer,notes,unsafe,rule_evaluation)values(p_organisation_id,r.id,p_mission_id,q->>'id',q,applicable,answer,nullif(submitted->>'notes',''),unsafe,jsonb_build_object('operator','bounded','applicable',applicable));if unsafe then select * into haz from public.platform_hazard_versions where id=(q->>'hazardVersionId')::uuid;select x into c from jsonb_array_elements(coalesce(p_payload->'controls','[]'))x where x->>'questionId'=q->>'id'limit 1;insert into public.mission_hazard_instances(organisation_id,revision_id,mission_id,triggering_question_id,platform_hazard_id,platform_hazard_version_id,platform_hazard_version,platform_hazard_snapshot,risk_category,likelihood,consequence,initial_score,notes)values(p_organisation_id,r.id,p_mission_id,q->>'id',haz.hazard_id,haz.id,haz.version_number,to_jsonb(haz),q->>'riskCategory',nullif(c->>'likelihood','')::integer,nullif(c->>'consequence','')::integer,nullif(c->>'likelihood','')::integer*nullif(c->>'consequence','')::integer,nullif(c->>'hazardNotes',''))returning * into hinst;if nullif(c->>'ownerPersonnelId','')is not null then select * into owner from public.personnel where organisation_id=p_organisation_id and id=(c->>'ownerPersonnelId')::uuid and archived_at is null and is_active;if not found then raise exception 'control owner is invalid';end if;end if;insert into public.mission_risk_control_instances(organisation_id,revision_id,mission_id,hazard_instance_id,triggering_question_id,template_control_id,risk_category,required_mitigation,owner_personnel_id,owner_personnel_snapshot,due_status,completion_state,completed_at,likelihood,consequence,initial_score,mitigation,residual_likelihood,residual_consequence,residual_score,evidence,notes,derivation_provenance)values(p_organisation_id,r.id,p_mission_id,hinst.id,q->>'id',q->'control'->>'id',q->>'riskCategory',q->'control'->>'description',owner.id,case when owner.id is null then null else jsonb_build_object('id',owner.id,'version',owner.row_version,'name',owner.full_name)end,coalesce(q->'control'->>'dueStatus','BEFORE_AUTHORISATION'),coalesce(c->>'completionState','OPEN'),case when c->>'completionState'='COMPLETE'then now()else null end,nullif(c->>'likelihood','')::integer,nullif(c->>'consequence','')::integer,nullif(c->>'likelihood','')::integer*nullif(c->>'consequence','')::integer,nullif(c->>'mitigation',''),nullif(c->>'residualLikelihood','')::integer,nullif(c->>'residualConsequence','')::integer,nullif(c->>'residualLikelihood','')::integer*nullif(c->>'residualConsequence','')::integer,coalesce(c->'evidence','[]'),nullif(c->>'notes',''),jsonb_build_object('templateVersion',tv.version_number,'questionId',q->>'id','platformHazardVersion',haz.version_number));owner=null;end if;submitted=null;end loop;
for a in select value from jsonb_array_elements(coalesce(p_payload->'attachments','[]'))loop insert into public.mission_jsa_attachments(organisation_id,revision_id,mission_id,internal_file_id,file_version,sha256_checksum,evidence_type,access_classification,provenance,attached_by_internal_user_id)values(p_organisation_id,r.id,p_mission_id,(a->>'internalFileId')::uuid,(a->>'fileVersion')::integer,a->>'checksum',a->>'evidenceType',a->>'accessClassification',coalesce(a->'provenance','{}'),p_actor_internal_user_id);end loop;insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(p_organisation_id,p_actor_internal_user_id,'mission.jsa_saved','mission',p_mission_id,jsonb_build_object('revision_id',r.id,'version',r.version_number,'template_version',r.template_version,'policy_version',r.policy_version));insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(p_organisation_id,'operational.mission.jsa_saved','mission',p_mission_id,jsonb_build_object('revision_id',r.id,'version',r.version_number));return jsonb_build_object('record',(select x from public.ftf_read_mission_jsa(p_organisation_id,p_mission_id,false)x));end$$;

create function public.ftf_evaluate_mission_jsa_readiness(p_organisation_id uuid,p_mission_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare r public.mission_jsa_revisions%rowtype;threshold integer;blockers jsonb='[]';warnings jsonb='[]';categories jsonb='{}';outstanding jsonb='[]';completed jsonb='[]';missing integer;controls integer;approved boolean;overall text;begin select * into r from public.mission_jsa_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id order by version_number desc limit 1;if not found then return jsonb_build_object('overallState','NOT_STARTED','ready',false,'blockers',jsonb_build_array(jsonb_build_object('code','JSA_NOT_STARTED','category','Questions','message','Complete the Mission JSA.')),'warnings','[]'::jsonb,'categories',jsonb_build_object('Questions','OUTSTANDING'),'outstandingSections',jsonb_build_array('Questions','Hazards','Controls','Attachments','Risk','Approval'),'completedSections','[]'::jsonb);end if;threshold=(r.policy_snapshot->>'residual_risk_threshold')::integer;select count(*)into missing from public.mission_jsa_responses where organisation_id=p_organisation_id and revision_id=r.id and applicable and(question_snapshot->>'mandatory')::boolean and answer is null;if missing>0 then blockers=blockers||jsonb_build_array(jsonb_build_object('code','QUESTION_UNANSWERED','category','Questions','message',missing||' mandatory Mission check(s) remain unanswered.'));outstanding=outstanding||'"Questions"'::jsonb;else completed=completed||'"Questions"'::jsonb;end if;select count(*)into missing from public.mission_hazard_instances where organisation_id=p_organisation_id and revision_id=r.id and(likelihood is null or consequence is null);if missing>0 then blockers=blockers||jsonb_build_array(jsonb_build_object('code','HAZARD_UNASSESSED','category','Hazards','message',missing||' triggered hazard(s) require assessment.'));outstanding=outstanding||'"Hazards"'::jsonb;else completed=completed||'"Hazards"'::jsonb;end if;select count(*)into controls from public.mission_risk_control_instances where organisation_id=p_organisation_id and revision_id=r.id;select count(*)into missing from public.mission_risk_control_instances where organisation_id=p_organisation_id and revision_id=r.id and owner_personnel_id is null;if missing>0 then blockers=blockers||jsonb_build_array(jsonb_build_object('code','CONTROL_OWNER_MISSING','category','Controls','message',missing||' required control(s) need an owner.'));end if;select count(*)into missing from public.mission_risk_control_instances where organisation_id=p_organisation_id and revision_id=r.id and(initial_score>=threshold and(coalesce(trim(mitigation),'')=''or residual_score is null));if missing>0 then blockers=blockers||jsonb_build_array(jsonb_build_object('code','CONTROL_INCOMPLETE','category','Controls','message',missing||' required control(s) need mitigation and residual assessment.'));end if;select count(*)into missing from public.mission_risk_control_instances where organisation_id=p_organisation_id and revision_id=r.id and due_status='BEFORE_AUTHORISATION'and completion_state<>'COMPLETE';if missing>0 then blockers=blockers||jsonb_build_array(jsonb_build_object('code','CONTROL_INCOMPLETE','category','Controls','message',missing||' required control(s) must be completed before authorisation.'));end if;if exists(select 1 from public.mission_risk_control_instances where organisation_id=p_organisation_id and revision_id=r.id and residual_score>=threshold)then blockers=blockers||jsonb_build_array(jsonb_build_object('code','RESIDUAL_RISK_TOO_HIGH','category','Risk','message','Residual risk exceeds the organisation threshold of '||(threshold-1)||'.'));outstanding=outstanding||'"Risk"'::jsonb;else completed=completed||'"Risk"'::jsonb;end if;if exists(select 1 from public.mission_risk_control_instances where organisation_id=p_organisation_id and revision_id=r.id and(owner_personnel_id is null or(initial_score>=threshold and(coalesce(trim(mitigation),'')=''or residual_score is null))or(due_status='BEFORE_AUTHORISATION'and completion_state<>'COMPLETE')))then outstanding=outstanding||'"Controls"'::jsonb;else completed=completed||'"Controls"'::jsonb;end if;completed=completed||'"Attachments"'::jsonb;approved=exists(select 1 from public.mission_jsa_approvals where organisation_id=p_organisation_id and revision_id=r.id);if not approved then blockers=blockers||jsonb_build_array(jsonb_build_object('code','JSA_NOT_APPROVED','category','Approval','message','The assigned Pilot in Command must approve this JSA.'));outstanding=outstanding||'"Approval"'::jsonb;else completed=completed||'"Approval"'::jsonb;end if;overall=case when jsonb_array_length(blockers)=0 then case when jsonb_array_length(warnings)>0 then'WARNING'else'READY'end when missing>0 then'INCOMPLETE'else'BLOCKED'end;categories=jsonb_build_object('Questions',case when outstanding?'Questions'then'OUTSTANDING'else'COMPLETE'end,'Hazards',case when outstanding?'Hazards'then'OUTSTANDING'else'COMPLETE'end,'Controls',case when outstanding?'Controls'then'OUTSTANDING'else'COMPLETE'end,'Attachments','COMPLETE','Risk',case when outstanding?'Risk'then'OUTSTANDING'else'COMPLETE'end,'Approval',case when outstanding?'Approval'then'OUTSTANDING'else'COMPLETE'end);return jsonb_build_object('overallState',overall,'ready',jsonb_array_length(blockers)=0,'blockers',blockers,'warnings',warnings,'categories',categories,'outstandingSections',outstanding,'completedSections',completed,'revisionId',r.id,'templateVersion',r.template_version,'policyVersion',r.policy_version);end$$;

create function public.ftf_approve_mission_jsa(p_organisation_id uuid,p_actor_internal_user_id uuid,p_mission_id uuid,p_revision_id uuid,p_expected_version integer)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare r public.mission_jsa_revisions%rowtype;person public.personnel%rowtype;assignment public.mission_personnel_assignments%rowtype;readiness jsonb;approval public.mission_jsa_approvals%rowtype;current integer;begin select coalesce(max(version_number),0)into current from public.mission_jsa_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id;if current<>p_expected_version then return jsonb_build_object('conflict',true,'current_version',current);end if;select * into r from public.mission_jsa_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id and id=p_revision_id;if not found then return jsonb_build_object('not_found',true);end if;select a.* into assignment from public.mission_personnel_assignments a join public.mission_personnel_revisions pr on pr.organisation_id=a.organisation_id and pr.id=a.revision_id where a.organisation_id=p_organisation_id and a.mission_id=p_mission_id and a.assignment_role='pilot_in_command'and pr.version_number=(select max(version_number)from public.mission_personnel_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id);if not found then return jsonb_build_object('pic_required',true);end if;select * into person from public.personnel where organisation_id=p_organisation_id and id=assignment.personnel_id and internal_user_id=p_actor_internal_user_id and archived_at is null;if not found then return jsonb_build_object('pic_forbidden',true);end if;readiness=public.ftf_evaluate_mission_jsa_readiness(p_organisation_id,p_mission_id);if exists(select 1 from jsonb_array_elements(readiness->'blockers')b where b->>'category'<>'Approval')then return jsonb_build_object('readiness_blocked',true,'readiness',readiness);end if;if r.policy_snapshot->>'approval_model'<>'PIC_SELF_APPROVAL'then return jsonb_build_object('policy_unsatisfied',true);end if;insert into public.mission_jsa_approvals(organisation_id,operating_location_id,mission_id,revision_id,approval_role,approving_personnel_id,approving_personnel_version,approving_personnel_snapshot,policy_requirement_snapshot,approved_by_internal_user_id)values(p_organisation_id,r.operating_location_id,p_mission_id,r.id,'pilot_in_command',person.id,person.row_version,assignment.personnel_snapshot,r.policy_snapshot,p_actor_internal_user_id)returning * into approval;insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(p_organisation_id,p_actor_internal_user_id,'mission.jsa_approved','mission',p_mission_id,jsonb_build_object('revision_id',r.id,'approval_id',approval.id,'approving_personnel_id',person.id));insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(p_organisation_id,'operational.mission.jsa_approved','mission',p_mission_id,jsonb_build_object('revision_id',r.id,'approval_id',approval.id));return jsonb_build_object('record',(select x from public.ftf_read_mission_jsa(p_organisation_id,p_mission_id,false)x),'readiness',public.ftf_evaluate_mission_jsa_readiness(p_organisation_id,p_mission_id));end$$;

revoke all on function public.ftf_provision_jsa_policy(),public.ftf_provision_jsa_permissions(),public.ftf_evaluate_jsa_rule(jsonb,jsonb,jsonb),public.ftf_read_mission_jsa(uuid,uuid,boolean),public.ftf_save_mission_jsa(uuid,uuid,uuid,integer,jsonb),public.ftf_evaluate_mission_jsa_readiness(uuid,uuid),public.ftf_approve_mission_jsa(uuid,uuid,uuid,uuid,integer)from public,anon,authenticated;
grant execute on function public.ftf_evaluate_jsa_rule(jsonb,jsonb,jsonb),public.ftf_read_mission_jsa(uuid,uuid,boolean),public.ftf_save_mission_jsa(uuid,uuid,uuid,integer,jsonb),public.ftf_evaluate_mission_jsa_readiness(uuid,uuid),public.ftf_approve_mission_jsa(uuid,uuid,uuid,uuid,integer)to service_role;
